#[allow(dead_code)]mod baseline;
use std::{hint::black_box as bb,time::Instant};
#[inline(never)]
fn old_sample(s:&mut baseline::Sampler,l:&[f32])->usize {s.sample(l,&[])}
#[inline(never)]
fn new_sample(s:&mut phlegm_core::sampler::Sampler,l:&[f32])->usize {s.try_sample(l,&[]).unwrap()}
fn main(){
 let mut logits=vec![0f32;262144];for(i,v)in logits.iter_mut().enumerate(){*v=((i*7331)%100000)as f32/10000.0;}
 for(t,k,p)in [(0.,0,1.),(1.,64,0.95)]{
  let mut old=baseline::Sampler::new(t,k,p,1.,Some(1));let mut new=phlegm_core::sampler::Sampler::new(t,k,p,1.,Some(1));let mut a=vec![];let mut b=vec![];
  for round in 0..15 {for mode in if round%2==0{[false,true]}else{[true,false]}{let start=Instant::now();for _ in 0..100{if mode{bb(new_sample(bb(&mut new),bb(&logits)));}else{bb(old_sample(bb(&mut old),bb(&logits)));}}let ms=start.elapsed().as_secs_f64()*10.0;if round>0{if mode{b.push(ms)}else{a.push(ms)}}}}
  println!("t={t} k={k} p={p} baseline_ms={a:?} current_ms={b:?}");
 }
}
